#!/usr/bin/env bash
# run_tests.sh — Runs the ShapERuntime test suite via xcodebuild.
#
# xcodebuild compiles Metal shaders and bundles default.metallib alongside
# the test runner, so MLX can initialise its GPU stream correctly.
# This avoids the "Failed to load the default metallib" crash that occurs
# when using plain `swift test` from the command line.
#
# Usage:
#   ./run_tests.sh                          # all tests
#   ./run_tests.sh Text300MTransformerTests # filter to one suite

set -euo pipefail

FILTER="${1:-}"

DESTINATION="platform=macOS"
# The autogenerated Package scheme exists in a clean clone and is configured
# for tests; the product scheme is not.
SCHEME="ShapERuntime-Package"

run_xcodebuild() {
    if [[ -n "$FILTER" ]]; then
        xcodebuild test \
            -scheme "$SCHEME" \
            -destination "$DESTINATION" \
            -only-testing:"ShapERuntimeTests/$FILTER"
    else
        xcodebuild test \
            -scheme "$SCHEME" \
            -destination "$DESTINATION"
    fi
}

# Decide formatting before the single test run. Do not retry after a failure:
# a passing retry would mask an intermittent test failure.
if command -v xcbeautify >/dev/null 2>&1; then
    run_xcodebuild | xcbeautify
else
    run_xcodebuild
fi
